import {defaultState,restoreState,slideKey,mapConcurrent,validateProduct,price,quotePrice,isBundle,budget,money,esc,makeSlides,selectedProducts,categories} from './core.js';
import {initProductReorder} from './reorder.js';
import {parsePageSelection} from './export-pages.js';
import {SELECTION_SORTS,sortedProducts,setSelectionSort,moveSelectedProduct} from './core.js';
import {createSharedLibrary} from './shared-library.js';
import {createSharedQuotes} from './shared-quotes.js';
import {drawSlide,imageSource,loadImage} from './render.js';
const icons={grip:'M9 5h.01 M15 5h.01 M9 12h.01 M15 12h.01 M9 19h.01 M15 19h.01',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 13h8 M8 17h5',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',folder:'M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z',help:'M9.1 9a3 3 0 0 1 5.8 1c0 2-3 3-3 3 M12 17h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',plus:'M12 5v14 M5 12h14',download:'M12 3v12 M7 10l5 5 5-5 M5 16v5h14v-5',upload:'M12 16V3 M7 8l5-5 5 5 M4 16v5h16v-5',left:'m14 6-6 6 6 6',right:'m10 6 6 6-6 6',close:'m6 6 12 12 M6 18 18 6',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',edit:'m16 3 5 5-12 12-6 1 1-6z M14 5l5 5',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',check:'m5 12 4 4 10-10',arrow:'M12 19V5 M6 11l6-6 6 6',image:'M3 3h18v18H3z m1 14 5-5 4 4 4-6 3 4 M8 8h.01',save:'M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h12l4 4v12a2 2 0 0 1-2 2 M7 3v6h10V3 M7 21v-8h10v8',copy:'M9 9h12v12H9z M5 15H3V3h12v2',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.file}"/></svg>`;
let state=defaultState(),view='quote',page=0,query='',filterBrand='',filterCategory='',drafts=[],saveTimer,previewToken=0,busy=false,modalImage='',editingId=null;
let assistantPrompt='',assistantGroups=[],assistantCatalog=[],assistantMode='replace',assistantStockSource='website',assistantWarning='',assistantEngine='',assistantResult=null;
const assistantCategories=[['bo-tra','Bộ trà'],['bo-ca-phe','Bộ cà phê'],['bo-do-an','Bộ đồ ăn'],['chen-com','Chén cơm'],['binh-hoa','Bình hoa'],['binh-giu-nhiet','Bình giữ nhiệt'],['binh-nuoc','Bình nước'],['ly-su','Ly sứ'],['ly-duong-sinh','Ly dưỡng sinh'],['ly-coc','Ly, cốc'],['may-say-toc','Máy sấy tóc'],['ban-ui','Bàn ủi'],['may-hut-bui','Máy hút bụi'],['noi','Nồi'],['chao','Chảo']];

let previewTextBoxes=[],previewTextKey='';
const $=s=>document.querySelector(s),app=$('#app');
initProductReorder({root:app,canStart:()=>!busy&&view==='quote',onMove:(id,target,after)=>{if(!moveSelectedProduct(state,id,target,after))return false;changed();toast('Đã đổi thứ tự. Sắp xếp theo giá đã tắt.');return true;},announce:toast});
const db=await new Promise((resolve,reject)=>{const req=indexedDB.open('vigifts-quote-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('kv');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)}).catch(()=>null);
async function dbGet(key){if(!db)return null;return new Promise((resolve,reject)=>{const r=db.transaction('kv').objectStore('kv').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function dbPut(key,value){if(!db)throw Error('Trình duyệt chưa cho phép lưu dữ liệu. Hãy tải bản sao JSON để giữ dữ liệu.');return new Promise((resolve,reject)=>{const t=db.transaction('kv','readwrite');t.objectStore('kv').put(value,key);t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error)})}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4300)}
function fail(e){console.error(e);toast(e.message||'Chưa thực hiện được. Vui lòng thử lại.');}
function scheduleSave(){sharedLibrary.schedulePublish();clearTimeout(saveTimer);const status=$('#save-status');if(status)status.textContent='Đang lưu…';saveTimer=setTimeout(async()=>{try{await dbPut('current',structuredClone(state));if($('#save-status'))$('#save-status').innerHTML='<span class="dot"></span>Đã lưu trên máy này'}catch(e){if($('#save-status'))$('#save-status').textContent='Chưa lưu — hãy tải bản sao';toast(e.message)}},450)}
function setBusy(title,detail=''){busy=true;$('#busy').hidden=false;$('#busy-title').textContent=title;$('#busy-detail').textContent=detail}
function clearBusy(){busy=false;$('#busy').hidden=true}
function btn(label,action,ic='',cls='',attrs=''){return `<button class="btn ${cls}" data-action="${action}" ${attrs}>${ic?icon(ic):''}${label}</button>`}
function field(label,name,value,type='text',attrs=''){return `<div class="field"><label class="label" for="${name}">${label}</label><input class="input" id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`}
function metaField(label,name,type='text'){return field(label,'meta-'+name,state.meta[name],type,`data-meta="${name}"`)}
function switchRow(label,key){return `<label class="switch-row">${label}<input type="checkbox" data-setting="${key}" ${state.settings[key]?'checked':''}></label>`}
function photoTag(p,cls='mini-photo'){return p.image?`<img class="${cls}" src="${esc(imageSource(p.image))}" alt="${esc(p.name)}" loading="lazy">`:`<div class="${cls}" style="display:grid;place-items:center;color:#90a096">${icon('image')}</div>`}
function crmSession(){try{return localStorage.getItem('bn-v2-session')||sessionStorage.getItem('bn-v2-session')||''}catch{return ''}}
async function libraryApi(path,method='GET',body){const headers={'Content-Type':'application/json'},token=crmSession();if(token)headers.Authorization='Bearer '+token;const response=await fetch(new URL(path,import.meta.url),{method,headers,body:body?JSON.stringify(body):undefined});let data;try{data=await response.json()}catch{throw Error('Máy chủ chưa trả dữ liệu thư viện. Thử lại sau.')}if(!response.ok){const e=Error(data.error||'Chưa truy cập được thư viện chung.');e.status=response.status;throw e;}return data;}
const pendingKey=(owner,id)=>'catalogue-shared-pending:'+owner+':'+id;
async function libraryPending(owner){if(!db)return[];return new Promise((resolve,reject)=>{const out=[],r=db.transaction('kv').objectStore('kv').openCursor(IDBKeyRange.bound('catalogue-shared-pending:'+owner+':','catalogue-shared-pending:'+owner+':\uffff'));r.onsuccess=()=>{const c=r.result;if(!c){resolve(out);return}if(String(c.key).startsWith('catalogue-shared-pending:'+owner+':'))out.push(c.value);c.continue()};r.onerror=()=>reject(r.error)})}
async function libraryPendingWrite(owner,id,value){if(!db)throw Error('Chưa lưu được hàng chờ trên máy. Cho phép lưu trữ hoặc tải bản sao.');return new Promise((resolve,reject)=>{const t=db.transaction('kv','readwrite'),kv=t.objectStore('kv');if(value)kv.put(value,pendingKey(owner,id));else kv.delete(pendingKey(owner,id));kv.put(structuredClone(state),'current');t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error)})}
const sharedLibrary=createSharedLibrary({api:libraryApi,identity:crmSession,getProducts:()=>state.products,getSelected:()=>state.selected,toast,
 priceOf:(product,row)=>{const picked=state.products.find(p=>(p.sharedId===row.id||p.id===row.localId)&&state.selected.includes(p.id));return quotePrice(picked||{...product,discount:product.brand==='LocknLock'?state.settings.lockDiscount:product.brand==='Minh Long'?state.settings.minhDiscount:0,fee:state.settings.fee,override:null},state)},
 onPick:row=>{if(row.localId){state.selected=state.selected.includes(row.localId)?state.selected.filter(id=>id!==row.localId):[...state.selected,row.localId];changed();return;}const selected=state.products.find(p=>p.sharedId===row.id&&state.selected.includes(p.id));if(selected){state.selected=state.selected.filter(id=>id!==selected.id);changed();return;}let previous=state.products.find(p=>p.sharedId===row.id);const p=row.product,copy=validateProduct({...p,id:previous?.id||crypto.randomUUID(),sharedId:row.id,sharedRevision:row.revision,qty:1,discount:p.brand==='LocknLock'?state.settings.lockDiscount:p.brand==='Minh Long'?state.settings.minhDiscount:0,fee:state.settings.fee,override:null});if(previous)Object.assign(previous,copy);else{if(state.products.length>=1000){toast('Báo giá/thư viện trên máy đạt 1.000 sản phẩm. Lưu bản sao trước khi tạo báo giá mới.');return;}state.products.push(copy);}state.selected.push(copy.id);changed();},
 onPublished:row=>{const p=state.products.find(p=>p.id===row.clientId);if(p){p.sharedId=row.id;p.sharedRevision=row.revision;p.sharedPendingFor='';}},
 pin:(id,owner)=>{const p=state.products.find(p=>p.id===id);if(p)p.sharedPendingFor=owner;},
 pending:libraryPending,savePending:(owner,id,value)=>libraryPendingWrite(owner,id,value),removePending:(owner,id)=>libraryPendingWrite(owner,id,null)
});
async function quotePendingWrite(owner,id,value){if(!db)throw Error('Cho phép lưu trữ để giữ yêu cầu lưu báo giá.');return new Promise((resolve,reject)=>{const t=db.transaction('kv','readwrite'),kv=t.objectStore('kv'),key='catalogue-quote-save:'+owner+':'+id;if(value)kv.put(value,key);else kv.delete(key);kv.put(structuredClone(state),'current');kv.put(structuredClone(drafts),'drafts');t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error)})}
const sharedQuotes=createSharedQuotes({api:libraryApi,identity:crmSession,getState:()=>state,getDrafts:()=>drafts,toast,confirm:confirmAction,
 setDocument:(snapshot,cloud)=>{state=restoreState(snapshot);state.cloudQuote=cloud;page=0;view='quote';changed();},
 persist:async()=>{clearTimeout(saveTimer);await dbPut('current',structuredClone(state));await dbPut('drafts',structuredClone(drafts));},
 remember:async(id,snapshot,result,owner)=>{const d={id,shared:true,owner,updated:Date.now(),state:{...structuredClone(snapshot),cloudQuote:{id,revision:result.revision,owner}}};const index=drafts.findIndex(v=>v.id===id);if(index<0)drafts.unshift(d);else drafts[index]=d;},
 getPending:(owner,id)=>dbGet('catalogue-quote-save:'+owner+':'+id),putPending:quotePendingWrite
});
function render(){
 const count=selectedProducts(state).length;
 app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">VIGIFTS<small>BÁCH NGÂN</small></div><div class="side-label">Không gian làm việc</div><nav>${[['quote','file','Tạo báo giá'],['assistant','search','Trợ lý sản phẩm'],['products','grid','Sản phẩm'],['drafts','folder','Báo giá đã lưu'],['help','help','Hướng dẫn']].map(([id,ic,label])=>`<button class="nav ${view===id?'active':''}" data-action="nav" data-view="${id}">${icon(ic)}<span>${label}</span></button>`).join('')}</nav><div class="side-foot"><strong>QUÀ TẶNG DOANH NGHIỆP</strong><br>Chăm chút từng món quà.<br><br>Mẫu: VIGIFTS - BÁCH NGÂN<br>QR v2 · Khung 2 × 2</div></aside><main class="main"><header class="topbar"><div class="crumb">Không gian làm việc <span style="padding:0 9px;color:#b6c2bb">/</span><b>${{quote:'Báo giá của bạn',assistant:'Trợ lý sản phẩm',products:'Thư viện sản phẩm',drafts:'Báo giá đã lưu',help:'Hướng dẫn sử dụng'}[view]}</b></div><div class="top-actions"><span class="saved" id="save-status"><span class="dot"></span>${db?'Lưu trên máy này':'Chưa bật lưu trữ'}</span>${btn('PowerPoint','export-pptx','file','',count?'':'disabled')}${btn('Xuất PDF','export-pdf','download','primary',count?'':'disabled')}<div class="avatar">VG</div></div></header><section class="workspace">${view==='quote'?quoteView():view==='assistant'?assistantView():view==='products'?productsView():view==='drafts'?draftView():helpView()}</section></main></div>`;
 if(view==='drafts')sharedQuotes.mount($('#shared-quotes-root'));else sharedQuotes.unmount();
 if(view==='products')sharedLibrary.mount($('#shared-library-root'));else sharedLibrary.unmount();
 if(view==='quote'){$('.preview-top').insertAdjacentHTML('beforeend',btn('Sửa chữ trang này','edit-page-text','edit','small'));$('.page-head .head-buttons').insertAdjacentHTML('afterbegin',btn('Trợ lý sản phẩm','nav','search','','data-view="assistant"')+btn('Nhập Excel','import-excel','upload'));$('[data-setting="regular"]').closest('label').insertAdjacentHTML('afterend',switchRow('Giá theo bộ 10 SP (đơn giá × 10)','bundle10')+bundlePageOptions());updatePreview();}
}
function bundlePageOptions(){
 if(!state.settings.bundle10)return '';
 const slides=makeSlides(state),pages=slides.map((s,i)=>({...s,number:i+1})).filter(s=>s.type==='products');
 const count=pages.filter(s=>s.items.every(p=>isBundle(p,state))).length;
 return `<div class="bundle-scope"><div class="label">Chọn trang cần ×10 <span class="count-badge">${count} / ${pages.length}</span></div>${pages.length?`<div class="bundle-page-list">${pages.map(s=>`<label class="bundle-page"><input type="checkbox" data-bundle-ids="${esc(JSON.stringify(s.items.map(p=>p.id)))}" ${s.items.every(p=>isBundle(p,state))?'checked':''}><span><strong>Trang ${s.number} · ${esc(s.brand)}</strong><small>${esc(s.category)} · ${s.items.length} SP${s.bundle10?' · Bộ 10 SP':''}</small></span></label>`).join('')}</div>`:'<p class="hint">Chọn sản phẩm để hiện danh sách trang.</p>'}<p class="hint">Chỉ trang được tick tính giá bộ 10. Khi giá thay đổi, trang được chuyển sang nhóm ngân sách phù hợp; lựa chọn vẫn đi theo sản phẩm, không theo số trang cũ.</p></div>`;
}
function quoteView(){const selected=sortedProducts(state),slides=makeSlides(state);page=Math.min(page,slides.length-1);
 return `<div class="page-head"><div><div class="eyebrow">BÁO GIÁ DÙNG CHUNG</div><h1>Tạo một lời chào thật chỉn chu.</h1><p>Chọn sản phẩm, cá nhân hóa nội dung và gửi đến khách hàng của bạn.</p></div><div class="head-buttons">${btn('Báo giá mới','new-quote','plus')}${btn('Lưu báo giá chung','save-draft','save')}</div></div><div class="editor-layout"><div><div class="panel"><div class="preview-top"><div class="view-label">${icon('file')} Xem trước báo giá <span class="tag">QR v2</span></div><span class="hint" style="margin:0">16:9 · 4 sản phẩm/trang</span></div><div class="preview-stage"><div class="canvas-wrap"><canvas id="slide-canvas" aria-label="Xem trước trang báo giá"></canvas><div class="text-edit-layer" id="text-edit-layer" aria-label="Sửa chữ trực tiếp"></div>${!selected.length?`<div class="empty-overlay"><div class="empty-mark">${icon('grid')}</div><h3>Bắt đầu từ những món quà.</h3><p>Thêm sản phẩm để tạo báo giá đầu tiên theo mẫu VIGIFTS - BÁCH NGÂN.</p>${btn('Chọn sản phẩm','choose-products','plus','primary')}</div>`:''}</div></div><div class="preview-bottom"><span id="slide-description">Mẫu VIGIFTS - BÁCH NGÂN</span><div class="pager"><button class="icon-btn" data-action="prev" aria-label="Trang trước" ${page===0?'disabled':''}>${icon('left')}</button><span id="page-number">${page+1} / ${slides.length}</span><button class="icon-btn" data-action="next" aria-label="Trang sau" ${page>=slides.length-1?'disabled':''}>${icon('right')}</button></div></div></div><div class="panel selection"><div class="panel-title"><h3>Sản phẩm trong báo giá <span class="count-badge">${selected.length}</span></h3><div class="head-buttons">${selected.length?btn('Bỏ chọn tất cả','clear-selection','','small quiet'):''}${btn('Thêm sản phẩm','choose-products','plus','small')}</div></div>${selected.length?selectionTools():''}${selected.length?selected.map(p=>`<div class="product-row" data-product-id="${esc(p.id)}"><button type="button" class="icon-btn reorder-handle" data-reorder-handle aria-label="Sắp xếp ${esc(p.name)}" aria-describedby="selection-reorder-help" title="Kéo để sắp xếp; dùng phím mũi tên lên/xuống">${icon('grip')}</button>${photoTag(p)}<div class="row-info"><strong>${esc(p.name)}</strong><small>${esc(p.brand)} · ${esc(p.category)}${p.sku?' · '+esc(p.sku):''}</small>${[p.collection,p.pattern,p.color].filter(Boolean).length?`<small>${[p.collection,p.pattern,p.color].filter(Boolean).map(esc).join(' · ')}</small>`:''}${p.crmStock?`<small class="stock-evidence">Tồn khả dụng CRM: ${esc(p.crmStock.available.toLocaleString('vi-VN'))} · ${esc(new Date(p.crmStock.checkedAt).toLocaleString('vi-VN'))}</small>`:''}</div><span class="row-price">${(p.priceOnRequest?'Liên hệ':money(quotePrice(p,state)))}</span><label class="quantity"><span>SL</span><input type="number" min="1" max="1000000" data-qty="${esc(p.id)}" value="${p.qty}" aria-label="Số lượng ${esc(p.name)}"></label><div class="row-actions"><button class="icon-btn move" title="Đưa lên trước trong danh sách" data-action="move-up" data-id="${esc(p.id)}">${icon('arrow')}</button><button class="icon-btn" aria-label="Sửa sản phẩm" data-action="edit" data-id="${esc(p.id)}">${icon('edit')}</button><button class="icon-btn" aria-label="Bỏ khỏi báo giá" data-action="toggle" data-id="${esc(p.id)}">${icon('close')}</button></div></div>`).join('')+`<div class="summary"><span>Tổng các sản phẩm có giá${selected.some(p=>p.priceOnRequest)?" · chưa gồm sản phẩm Liên hệ":""}</span><b>${money(selected.reduce((n,p)=>n+quotePrice(p,state)*p.qty,0))}</b></div>`:`<div class="selection-empty"><p>Chưa có sản phẩm nào được chọn.</p>${btn('Thêm sản phẩm mới','add-product','plus','small')}</div>`}</div><p class="draft-mini">${selected.length-makeSlides(state).filter(s=>s.type==='products').reduce((n,s)=>n+s.items.length,0)} SP lẻ một mình trong nhóm được bỏ qua khi xuất; sản phẩm vẫn còn trong danh sách để anh/chị điều chỉnh.</p><p class="draft-mini">Bấm vào chữ trên trang để sửa · Ctrl+Enter lưu · Esc hủy. Đơn giá tính toán sửa trong thông tin sản phẩm.</p><p class="draft-mini">Bản đang sửa tự lưu trên máy. Bấm “Lưu báo giá chung” để cập nhật trên máy chủ cho toàn bộ nhân viên.</p></div><aside class="panel settings"><div class="panel-title"><h3>Thiết lập báo giá</h3><span class="tag">Cá nhân hóa</span></div><div class="panel-body"><div class="section-label">Thông tin khách hàng</div>${metaField('Tên báo giá','title')}${metaField('Khách hàng / Doanh nghiệp','customer')}${metaField('Mã báo giá','quoteNo')}${metaField('Ngày báo giá','date','date')}<div class="divider"></div><div class="section-label">Người tư vấn</div>${metaField('Tên nhân viên','employee')}${metaField('Hotline / Zalo','phone')}<div class="divider"></div><div class="section-label">Bố cục xuất file</div>${switchRow('Trang bìa','cover')}${switchRow('Trang chia ngân sách','dividers')}${switchRow('Trang cảm ơn','closing')}${switchRow('Mã QR và “Xem chi tiết”','qr')}${switchRow('Hiện giá niêm yết','regular')}${switchRow('Giá tăng dần trong danh mục','sortPrice')}<div class="field" style="margin-top:18px"><label class="label" for="quote-note">Ghi chú bên dưới giá</label><textarea class="input" id="quote-note" data-meta="note" maxlength="140">${esc(state.meta.note)}</textarea></div><div class="rules"><p><strong>THỨ TỰ PHÂN TRANG</strong><br>Ngân sách → Thương hiệu → Danh mục.<br>Mỗi trang tối đa 4 SP. Trang còn 2–3 SP được giữ; trang lẻ đúng 1 SP được bỏ qua khi xuất.</p></div><div class="head-buttons" style="margin-top:16px">${btn('Tải bản sao','backup','download','small')}${btn('Khôi phục','import-json','upload','small')}</div></div></aside></div>`;
}
function productsView(){return `<div class="shared-library-tools"><div class="head-buttons">${btn('Nhập Excel / CSV','import-excel','upload')}${btn('Thêm sản phẩm','add-product','plus','primary')}</div></div><div id="shared-library-root"></div>`;}
function draftView(){return `<div class="page-head"><div><div class="eyebrow">BÁO GIÁ DÙNG CHUNG</div><h1>Mỗi khách hàng, một lựa chọn.</h1><p>Toàn bộ nhân viên cùng mở và chỉnh sửa báo giá.</p></div>${btn('Tạo báo giá mới','new-quote','plus','primary')}</div><div id="shared-quotes-root"></div>`}
function helpView(){return `<div class="page-head"><div><div class="eyebrow">HƯỚNG DẪN NHANH</div><h1>Từ sản phẩm đến lời chào.</h1><p>Bốn bước để có một bản báo giá theo mẫu QR v2.</p></div></div><div class="help-grid">${[['Thêm sản phẩm','Vào Sản phẩm → Thêm sản phẩm. Dán link LocknLock hoặc Minh Long và chọn Lấy thông tin. Kiểm tra ảnh, mã, tên, giá niêm yết và chọn danh mục. Bạn cũng có thể tự nhập thông tin, tải ảnh từ máy.'],['Nhập file Excel','App đọc tab “Nhap link” của mẫu Excel đã tạo; nếu không có sẽ đọc sheet đầu tiên. Chỉ có link: app lấy thông tin từ web. Có sẵn tên và giá: app dùng dữ liệu trong file. Cột M “Không” sẽ được bỏ qua. Sheet “208 SP tham khao” không tự nhập.'],['Cá nhân hóa báo giá','Chọn những sản phẩm cần chào rồi vào Tạo báo giá. Điền khách hàng, tên nhân viên, số điện thoại. Mỗi trang chỉ chứa cùng thương hiệu, cùng danh mục, cùng khoảng ngân sách. Các sản phẩm không đủ 4 giữ trang cuối ít hơn 4 ô.'],['Xuất và lưu','Chọn PDF để gửi khách hoặc PowerPoint để tiếp tục sửa. Mẫu xuất là VIGIFTS - BACH NGAN - QR v2. Ảnh, QR, số tiền màu xanh và ghi chú theo mẫu. Lưu bản báo giá hoặc tải bản sao JSON để giữ dữ liệu.']].map(([title,body],i)=>`<article class="panel help-item"><span class="step">0${i+1}</span><h2>${title}</h2><p>${body}</p></article>`).join('')}</div><div class="inline-note">Giá khởi điểm của sản phẩm nhiều biến thể được ghi “Từ”. Giá website dùng để tính là giá niêm yết, không lấy giá khuyến mại để giảm thêm lần nữa. App không kèm sẵn sản phẩm cũ.</div>`}
async function updatePreview(rebuildText=true){const canvas=$('#slide-canvas');if(!canvas)return;const token=++previewToken,slides=makeSlides(state);page=Math.min(page,slides.length-1);const slide=slides[page],buffer=document.createElement('canvas'),fields=[];await drawSlide(buffer,slide,state,page+1,slides.length,null,1,fields);if(token!==previewToken||!$('#slide-canvas'))return;canvas.width=1280;canvas.height=720;canvas.getContext('2d').drawImage(buffer,0,0);previewTextBoxes=fields;previewTextKey=slideKey(slide);if(rebuildText)mountTextLayer(slide);$('#page-number').textContent=`${page+1} / ${slides.length}`;$('#slide-description').textContent=slide.type==='products'?`${slide.brand} / ${slide.category}`:({cover:'Trang bìa',divider:'Nhóm ngân sách',closing:'Trang cảm ơn',empty:'Mẫu trống · QR v2'}[slide.type]);$('[data-action="prev"]').disabled=page===0;$('[data-action="next"]').disabled=page>=slides.length-1;}
function changed(){scheduleSave();render()}
async function confirmAction(title,message){const d=$('#confirm-dialog');d.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2></div><div class="confirm-text">${esc(message)}</div><form method="dialog" class="modal-foot"><button class="btn" value="cancel">Hủy</button><button class="btn primary" value="confirm">Xác nhận</button></form>`;d.showModal();return new Promise(resolve=>d.addEventListener('close',()=>resolve(d.returnValue==='confirm'),{once:true}))}
async function openProduct(id=null){
 editingId=id;const old=state.products.find(p=>p.id===id);const p=old||{name:'',url:'',brand:'LocknLock',category:'',sku:'',image:'',regular:'',discount:state.settings.lockDiscount,fee:state.settings.fee,override:'',qty:1};modalImage=p.image;const d=$('#product-dialog');
 d.innerHTML=`<form id="product-form"><div class="modal-head"><div><h2>${old?'Sửa sản phẩm':'Thêm một món quà'}</h2><p>Thông tin được dùng cho PDF và PowerPoint.</p></div><button type="button" class="icon-btn" data-action="close-modal" aria-label="Đóng">${icon('close')}</button></div><div class="modal-body"><label class="label" for="p-url">Link sản phẩm (LocknLock / Minh Long)</label><div class="link-fetch"><input class="input" id="p-url" name="url" type="url" value="${esc(p.url)}" placeholder="https://locknlockonline.com/san-pham/…"><button type="button" class="btn" data-action="fetch-product">${icon('link')} Lấy thông tin</button></div><div class="form-grid"><div class="photo-side"><label class="upload-box" id="upload-box">${p.image?`<img src="${esc(imageSource(p.image))}" alt="Ảnh sản phẩm">`:icon('image')+'<span>Tải ảnh sản phẩm</span>'}<input type="file" id="p-image" accept="image/jpeg,image/png,image/webp" aria-label="Tải ảnh sản phẩm"></label><p class="hint">Chọn JPG, PNG hoặc WebP, tối đa 10 MB. Ảnh được tối ưu khi tải lên.</p></div><div>${field('Tên sản phẩm','p-name',p.name,'text','required maxlength="220"')}<div class="two"><div class="field"><label class="label" for="p-brand">Thương hiệu</label><select class="input" id="p-brand" name="brand">${[...new Set(['LocknLock','Minh Long',...(state.customBrands||[]).map(b=>b.name),p.brand,'Khác'])].map(s=>`<option ${p.brand===s?'selected':''}>${s}</option>`).join('')}</select></div>${field('Mã sản phẩm','p-sku',p.sku,'text','maxlength="100"')}</div>${field('Danh mục','p-category',p.category,'text','list="category-options" required maxlength="70"')}<datalist id="category-options">${[...new Set([...categories,...state.products.map(p=>p.category)])].map(c=>`<option value="${esc(c)}">`).join('')}</datalist><div class="two">${field('Bộ sưu tập','p-collection',p.collection||'','text','maxlength="100"')}${field('Hoa văn','p-pattern',p.pattern||'','text','maxlength="100"')}</div><div class="two">${field('Màu sắc','p-color',p.color||'','text','maxlength="100"')}${field('Ngày tạo sản phẩm nguồn (nếu biết)','p-created-at',p.createdAt?.slice(0,10)||'','date')}</div>${field('Giá niêm yết trên web (đ)','p-regular',p.regular,'number','min="1" max="10000000000" required step="1"')}<div class="two">${field('Chiết khấu (%)','p-discount',p.discount,'number','min="0" max="100" step="0.1" required')}${field('Phụ phí VAT + in (đ)','p-fee',p.fee,'number','min="0" max="100000000" step="1" required')}</div><div class="two">${field('Giá tự chào (đ) · tùy chọn','p-override',p.override??'','number','min="0" max="10000000000" placeholder="Để trống để tự tính"')}${field('Số lượng','p-qty',p.qty,'number','min="1" max="1000000" required')}</div><label class="switch-row">Sản phẩm có giá khởi điểm (“Từ”)<input type="checkbox" id="p-from" ${p.fromPrice?'checked':''}></label><div class="calc-box"><span>Giá đề xuất / sản phẩm</span><strong id="calculated-price">${money(price({...p,regular:p.regular||0}))}</strong></div><p id="product-error" class="error" role="alert"></p></div></div></div><div class="modal-foot">${old?'<button type="button" class="btn danger" data-action="delete-product" data-id="'+esc(id)+'">Xóa sản phẩm</button>':''}<button type="button" class="btn" data-action="close-modal">Hủy</button><button type="submit" class="btn primary">${old?'Lưu thay đổi':'Thêm & chọn báo giá'}</button></div></form>`;
 d.showModal();$('#p-name').focus();
}
function updateCalculation(){if(!$('#p-regular'))return;$('#calculated-price').textContent=money(price({regular:$('#p-regular').value,discount:$('#p-discount').value,fee:$('#p-fee').value,override:$('#p-override').value}))}
async function fetchProduct(url){const endpoint=new URL('api/product',import.meta.url);endpoint.searchParams.set('url',url);const r=await fetch(endpoint);const body=await r.json();if(!r.ok)throw Error(body.error||'Chưa lấy được thông tin. Bạn có thể nhập thủ công.');return body}
function applyFetched(p){for(const key of ['collection','pattern','color'])if(p[key])$('#p-'+key).value=p[key];if(p.createdAt)$('#p-created-at').value=p.createdAt.slice(0,10);$('#p-name').value=p.name;$('#p-sku').value=p.sku;$('#p-brand').value=p.brand;$('#p-regular').value=p.regular;$('#p-discount').value=p.brand==='LocknLock'?state.settings.lockDiscount:state.settings.minhDiscount;$('#p-from').checked=!!p.fromPrice;$('#p-url').value=p.url;modalImage=p.image;$('#upload-box').querySelector('img')?.remove();$('#upload-box').querySelector('span')?.remove();$('#upload-box').querySelector('svg')?.remove();if(p.image){const im=document.createElement('img');im.src=imageSource(p.image);im.alt=p.name;$('#upload-box').prepend(im)}if(!$('#p-category').value&&p.category)$('#p-category').value=p.category;updateCalculation()}
async function optimizePhoto(file){if(file.size>10*1024*1024)throw Error('Ảnh quá 10 MB. Hãy chọn ảnh nhỏ hơn.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Chỉ dùng JPG, PNG hoặc WebP.');const bmp=await createImageBitmap(file);const scale=Math.min(1,1000/Math.max(bmp.width,bmp.height));const c=document.createElement('canvas');c.width=Math.round(bmp.width*scale);c.height=Math.round(bmp.height*scale);const ctx=c.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(bmp,0,0,c.width,c.height);bmp.close();return c.toDataURL('image/jpeg',.86)}
function download(blob,filename){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),20000)}
const filename=ext=>(state.meta.quoteNo+' - '+(state.meta.customer||'VIGIFTS - BACH NGAN')).replace(/[<>:"/\\|?*\x00-\x1f]/g,'').slice(0,100)+'.'+ext;
async function exportFile(type,snapshot,pageNumbers){
 if(busy)return;const allSlides=makeSlides(snapshot),slides=pageNumbers.map(number=>({slide:allSlides[number-1],number}));setBusy(type==='pdf'?'Đang tạo PDF…':'Đang tạo PowerPoint…','Đang chuẩn bị ảnh và font chữ.');
 try{
  const missing=[];for(const p of slides.flatMap(({slide})=>slide.items||[])){if(p.image&&!await loadImage(p.image))missing.push(p.name)}
  if(missing.length)throw Error('Chưa tải được ảnh: '+missing.slice(0,2).join(', ')+'. Hãy sửa sản phẩm và tải ảnh từ máy rồi xuất lại.');
  const canvas=document.createElement('canvas');let pdf,ppt;
  if(type==='pdf'){pdf=await PDFLib.PDFDocument.create();pdf.setTitle(snapshot.meta.title);pdf.setAuthor('VIGIFTS - BÁCH NGÂN');}
  else{ppt=new PptxGenJS();ppt.defineLayout({name:'VIGIFTS',width:1280/96,height:720/96});ppt.layout='VIGIFTS';ppt.author=snapshot.meta.employee||'VIGIFTS - BÁCH NGÂN';ppt.subject=snapshot.meta.customer;ppt.title=snapshot.meta.title;ppt.company='VIGIFTS - BÁCH NGÂN';ppt.lang='vi-VN';ppt.theme={headFontFace:'Montserrat',bodyFontFace:'Montserrat',lang:'vi-VN'};}
  for(let i=0;i<slides.length;i++){$('#busy-detail').textContent=`Trang ${i+1} / ${slides.length}`;await drawSlide(canvas,slides[i].slide,snapshot,slides[i].number,allSlides.length,ppt?ppt.addSlide():null,pdf?2:1);if(pdf){const bytes=await (await fetch(canvas.toDataURL('image/png'))).arrayBuffer();const image=await pdf.embedPng(bytes);const page=pdf.addPage([960,540]);page.drawImage(image,{x:0,y:0,width:960,height:540})}await new Promise(r=>setTimeout(r,0));}
  if(pdf)download(new Blob([await pdf.save()],{type:'application/pdf'}),filename('pdf'));else await ppt.writeFile({fileName:filename('pptx')});toast('Đã xuất '+(pdf?'PDF':'PowerPoint')+' · '+slides.length+' trang.');
 }catch(e){fail(e)}finally{clearBusy()}
}
async function importFile(file){
 if(file.size>30*1024*1024)throw Error('File quá 30 MB. Vui lòng chia thành file nhỏ hơn.');
 if(file.name.toLowerCase().endsWith('.json')){const next=restoreState(JSON.parse(await file.text()));if(!await confirmAction('Khôi phục dữ liệu?','Dữ liệu đang mở sẽ được thay bằng nội dung file JSON.'))return;state=next;page=0;changed();toast('Đã khôi phục dữ liệu.');return;}
 const workbook=XLSX.read(await file.arrayBuffer(),{type:'array'}),sheet=workbook.Sheets[workbook.SheetNames.find(s=>s.toLowerCase().replaceAll(' ','')==='nhaplink')||workbook.SheetNames[0]],rows=XLSX.utils.sheet_to_json(sheet,{header:1,defval:''});
 const normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replaceAll('đ','d').toLowerCase().trim();let headerIndex=rows.findIndex(r=>r.some(c=>normalize(c)==='link san pham')||r.some(c=>normalize(c)==='ten san pham'));
 if(headerIndex<0)throw Error('Chưa thấy cột “Link sản phẩm” hoặc “Tên sản phẩm”. Hãy dùng file mẫu Nhap link.');
 const headers=rows[headerIndex].map(normalize),find=(...labels)=>labels.map(normalize).map(s=>headers.indexOf(s)).find(i=>i>=0)??-1;
 const cols={url:find('Link sản phẩm','Link'),name:find('Tên sản phẩm'),brand:find('Thương hiệu'),sku:find('Mã sản phẩm'),category:find('Danh mục'),regular:find('Giá niêm yết (đ)','Giá niêm yết'),discount:find('Chiết khấu'),image:find('Link ảnh ưu tiên'),include:find('Đưa vào PowerPoint')};
 const candidates=rows.slice(headerIndex+1).filter(r=>(cols.url>=0&&r[cols.url]||cols.name>=0&&r[cols.name])&&(cols.include<0||normalize(r[cols.include])!=='khong'));if(candidates.length>500)throw Error('Mỗi lần nhập tối đa 500 sản phẩm.');
 setBusy('Đang nhập sản phẩm…');let added=0,skipped=0;const errors=[];
 const known=new Set(state.products.map(p=>importUrlKey(p.url)).filter(Boolean));let completed=0;const pending=[];
 for(let i=0;i<candidates.length;i++){const row=candidates[i],url=cols.url>=0?row[cols.url]:'';const key=importUrlKey(url);if(key&&known.has(key)){skipped++;continue}if(key)known.add(key);pending.push({row,i})}
 try{const imported=await fetchImportBatches(pending.map(({row})=>({url:cols.url>=0?row[cols.url]:'',name:cols.name>=0?row[cols.name]:'',regular:cols.regular>=0?row[cols.regular]:'',image:cols.image>=0?row[cols.image]:''})));const results=await mapConcurrent(pending,6,async({row,i})=>{
  const get=k=>cols[k]>=0?row[cols[k]]:'';let p={url:get('url'),name:get('name'),brand:get('brand'),sku:get('sku'),category:get('category'),regular:get('regular'),image:get('image')};
  try{
   if(!p.name||!Number(p.regular)||p.url&&!p.image){if(!p.url)throw Error('Thiếu link hoặc tên/giá.');const supplied=Object.fromEntries(Object.entries(p).filter(([,v])=>v!==''&&v!==null&&v!==undefined));try{const entry=imported.get(importUrlKey(p.url));if(entry?.error)throw Error(entry.error);p={...(entry?.product||await fetchProduct(p.url)),...supplied};}catch(e){if(!p.name||!Number(p.regular))throw e;}}
   p.brand=String(p.brand||(/minhlongonline/.test(p.url)?'Minh Long':'LocknLock'));p.category=p.category||'Chưa phân loại';p.discount=get('discount')!==''?Number(get('discount')):p.brand==='LocknLock'?state.settings.lockDiscount:p.brand==='Minh Long'?state.settings.minhDiscount:0;if(p.discount>0&&p.discount<1)p.discount*=100;p.fee=state.settings.fee;p.qty=1;return validateProduct(p);
  }catch(e){errors.push({row:headerIndex+i+2,url:get('url'),error:e.message});return null}
  finally{completed++;$('#busy-detail').textContent=`Đã xử lý ${completed} / ${pending.length} · ${skipped} link trùng được bỏ qua · tối đa 6 mã đồng thời`;}
 });for(const p of results.filter(Boolean)){if(state.products.length>=1000){errors.push({row:'',url:p.url,error:'Thư viện đạt giới hạn 1.000 sản phẩm.'});continue}state.products.push(p);state.selected.push(p.id);added++;}
 }finally{clearBusy();changed()}
 toast(`Đã nhập ${added} sản phẩm${skipped?' · bỏ qua '+skipped+' link trùng':''}${errors.length?' · '+errors.length+' dòng chưa nhập':''}.`);
 if(errors.length){download(new Blob(['\ufeffDòng,Link,Lỗi\n'+errors.map(r=>[r.row,r.url,r.error].map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n')],{type:'text/csv;charset=utf-8'}),'Dong-chua-nhap.csv');}
}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action,id=b.dataset.id;
 try{
  if(action==='nav'){view=b.dataset.view;render()}
  else if(action==='choose-products'){view='products';render()}
  else if(action==='add-product')openProduct();
  else if(action==='edit')openProduct(id);
  else if(action==='close-modal')$('#product-dialog').close();
  else if(action==='toggle'){state.selected=state.selected.includes(id)?state.selected.filter(s=>s!==id):[...state.selected,id];changed()}
  else if(action==='clear-selection'){if(await confirmAction('Bỏ chọn toàn bộ sản phẩm?','Thư viện vẫn giữ sản phẩm, chỉ làm trống báo giá đang mở.')){state.selected=[];page=0;changed()}}
  else if(action==='delete-all'){if(await confirmAction('Xóa toàn bộ thư viện?','Toàn bộ sản phẩm trong thư viện và báo giá đang mở sẽ bị xóa khỏi máy này.')){state.products=[];state.selected=[];page=0;changed()}}
  else if(action==='delete-product'){if(await confirmAction('Xóa sản phẩm?','Sản phẩm này sẽ được xóa khỏi thư viện và báo giá đang mở.')){state.products=state.products.filter(p=>p.id!==id);state.selected=state.selected.filter(s=>s!==id);$('#product-dialog').close();changed()}}
  else if(action==='move-up'){const rows=sortedProducts(state),i=rows.findIndex(p=>p.id===id);if(i>0&&moveSelectedProduct(state,id,rows[i-1].id)){changed();toast('Đã đổi thứ tự trong danh mục.')}}
  else if(action==='refresh-details'){await refreshSelectionDetails()}
  else if(action==='prev'||action==='next'){page+=action==='next'?1:-1;updatePreview()}
  else if(action==='inline-text'){inlineTextEditor(b.dataset.position,b)}
  else if(action==='edit-page-text'){await editPageText()}
  else if(action==='assistant-add'){await assistantAdd()}
  else if(action==='assistant-range'){await assistantAdd(Number(b.dataset.index),true)}
  else if(action==='assistant-remove'){readAssistantGroups();assistantGroups.splice(Number(b.dataset.index),1);render()}
  else if(action==='assistant-categories'){await loadAssistantCategories()}
  else if(action==='assistant-interpret'){await assistantInterpret()}
  else if(action==='assistant-search'){await assistantSearch()}
  else if(action==='fetch-product'){const url=$('#p-url').value.trim();if(!url)throw Error('Vui lòng dán link sản phẩm.');b.disabled=true;b.textContent='Đang lấy…';$('#product-error').textContent='';try{applyFetched(await fetchProduct(url));toast('Đã lấy giá niêm yết và ảnh từ web.')}catch(e){$('#product-error').textContent=e.message}finally{b.disabled=false;b.innerHTML=icon('link')+' Lấy thông tin'}}
  else if(action==='select-filtered'){for(const p of state.products.filter(p=>(!filterBrand||p.brand===filterBrand)&&(!filterCategory||p.category===filterCategory)&&`${p.name} ${p.sku} ${p.category}`.toLocaleLowerCase('vi').includes(query.toLocaleLowerCase('vi'))))if(!state.selected.includes(p.id))state.selected.push(p.id);changed()}
  else if(action==='new-quote'){if(state.selected.length&&!await confirmAction('Tạo báo giá mới?','Báo giá đang mở sẽ được làm mới. Hãy lưu phương án hiện tại trước nếu cần.'))return;const products=state.products;state=defaultState();state.products=products;page=0;view='quote';changed()}
  else if(action==='save-draft'){b.disabled=true;b.textContent='Đang lưu lên máy chủ…';try{await sharedQuotes.save();}finally{b.disabled=false;b.textContent='Lưu báo giá chung';}}
  else if(action==='backup')download(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),filename('json'));
  else if(action==='import-excel'||action==='import-json'){$('#import-input').accept=action==='import-json'?'.json':'.xlsx,.xls,.csv';$('#import-input').multiple=action==='import-excel';$('#import-input').click()}
  else if(action==='export-pdf'||action==='export-pptx')openExportDialog(action==='export-pdf'?'pdf':'pptx');
 }catch(e){fail(e)}
});
document.addEventListener('input',e=>{const t=e.target;
 if(t.dataset.meta){state.meta[t.dataset.meta]=t.value.slice(0,t.dataset.meta==='note'?140:160);scheduleSave();updatePreview()}
 else if(t.id==='product-search'){const pos=t.selectionStart;query=t.value;render();$('#product-search').focus();$('#product-search').setSelectionRange(pos,pos)}
 else if(['p-regular','p-discount','p-fee','p-override'].includes(t.id))updateCalculation();
});
document.addEventListener('change',async e=>{const t=e.target;try{
 if(t.dataset.assistantRefresh!==undefined){const i=Number(t.dataset.assistantRefresh),newBrand=t.id.endsWith('-brand')?t.value:null;readAssistantGroups();if(newBrand){assistantGroups[i].brand=newBrand;const custom=(state.customBrands||[]).find(b=>b.name===newBrand);assistantGroups[i].provider=custom?structuredClone(custom):null;if(custom){assistantGroups[i].type='website';assistantGroups[i].categoryLabel=custom.categoryLabel;}if(assistantGroups[i].categoryId){assistantGroups[i].categoryId=0;assistantGroups[i].type='';}}render()}
 else if(t.dataset.bundleIds){const ids=JSON.parse(t.dataset.bundleIds),current=new Set(state.settings.bundle10Ids||[]);for(const id of ids){if(t.checked)current.add(id);else current.delete(id)}state.settings.bundle10Ids=[...current];changed()}
 else if(t.id==='selection-sort'){setSelectionSort(state,t.value);changed()}
 else if(t.dataset.setting){if(t.dataset.setting==='sortPrice')setSelectionSort(state,t.checked?'price':'manual');else state.settings[t.dataset.setting]=t.checked;changed()}
 else if(t.dataset.qty){const p=state.products.find(p=>p.id===t.dataset.qty);p.qty=Math.max(1,Math.min(1000000,Math.round(Number(t.value)||1)));changed()}
 else if(t.id==='filter-brand'){filterBrand=t.value;render()}
 else if(t.id==='filter-category'){filterCategory=t.value;render()}
 else if(t.id==='p-brand'){$('#p-discount').value=t.value==='LocknLock'?state.settings.lockDiscount:t.value==='Minh Long'?state.settings.minhDiscount:0;updateCalculation()}
 else if(t.id==='p-image'&&t.files[0]){modalImage=await optimizePhoto(t.files[0]);$('#upload-box').querySelector('img')?.remove();$('#upload-box').querySelector('svg')?.remove();$('#upload-box').querySelector('span')?.remove();const im=document.createElement('img');im.src=modalImage;im.alt='Ảnh sản phẩm';$('#upload-box').prepend(im)}
 else if(t.id==='import-input'&&t.files[0]){const files=Array.from(t.files);t.value='';for(const f of files)await importFile(f)}
 }catch(e){fail(e)}});
document.addEventListener('submit',e=>{if(e.target.id!=='product-form')return;e.preventDefault();try{const prior=state.products.find(p=>p.id===editingId);const date=$('#p-created-at').value;const p=validateProduct({...prior,id:editingId,collection:$('#p-collection').value,pattern:$('#p-pattern').value,color:$('#p-color').value,createdAt:date===(prior?.createdAt?.slice(0,10)||'')?prior?.createdAt:date,createdAtSource:date===(prior?.createdAt?.slice(0,10)||'')?prior?.createdAtSource:null,name:$('#p-name').value,brand:$('#p-brand').value,sku:$('#p-sku').value,category:$('#p-category').value,url:$('#p-url').value,image:modalImage,regular:$('#p-regular').value,discount:$('#p-discount').value,fee:$('#p-fee').value,override:$('#p-override').value,qty:$('#p-qty').value,fromPrice:$('#p-from').checked});const old=state.products.findIndex(q=>q.id===p.id);if(old>=0)state.products[old]=p;else state.products.push(p);if(!state.selected.includes(p.id))state.selected.push(p.id);$('#product-dialog').close();changed();toast(old>=0?'Đã lưu thay đổi.':'Đã thêm và chọn vào báo giá.')}catch(e){$('#product-error').textContent=e.message}});
try{const stored=await dbGet('current');if(stored)state=restoreState(stored);drafts=(await dbGet('drafts')||[]).filter(d=>{try{restoreState(d.state);return true}catch{return false}})}catch(e){toast('Chưa đọc được dữ liệu cũ. Có thể khôi phục từ bản sao JSON.')}
render();sharedLibrary.bootstrap();window.vigifts={getState:()=>structuredClone(state),getSlides:()=>makeSlides(state)};

function assistantCategoryOptions(c){if(c.provider)return [...new Map([{name:c.provider.categoryLabel,url:c.provider.collectionUrl},...(c.provider.collections||[])].map(v=>[v.url,v])).values()].map(v=>`<option value="${esc(v.url)}" ${v.url===c.provider.collectionUrl?"selected":""}>${esc(v.name)}</option>`).join('');const value=c.categoryId?'web:'+c.brand+':'+c.categoryId:'type:'+c.type;return `<option value="type:">Chọn danh mục</option><optgroup label="Danh mục thông dụng">${assistantCategories.map(([v,l])=>`<option value="type:${v}" ${value==='type:'+v?'selected':''}>${l}</option>`).join('')}</optgroup>${['Minh Long','LocknLock'].filter(b=>c.brand==='both'||c.brand===b).map(b=>`<optgroup label="Danh mục website ${b}">${assistantCatalog.filter(v=>v.brand===b).map(v=>`<option value="web:${b}:${v.id}" ${value===`web:${b}:${v.id}`?'selected':''}>${esc(v.label)} (${v.count})</option>`).join('')}</optgroup>`).join('')}`;}
function assistantGroupCard(c,i){const prefix='ag-'+i+'-';return `<article class="panel assistant-group" data-assistant-group="${i}"><div class="panel-title"><h3>Nhóm ${i+1} · Danh mục & ngân sách</h3><div class="head-buttons">${btn('Thêm mức giá','assistant-range','plus','small',`data-index="${i}"`)}${btn('Bỏ nhóm','assistant-remove','close','small',`data-index="${i}"`)}</div></div><div class="panel-body"><div class="two"><div class="field"><label class="label" for="${prefix}brand">Thương hiệu · nhóm ${i+1}</label><select class="input" id="${prefix}brand" data-assistant-refresh="${i}">${[['Minh Long','Minh Long'],['LocknLock','LocknLock'],['both','LocknLock & Minh Long'],...(state.customBrands||[]).map(b=>[b.name,b.name])].map(([v,l])=>`<option value="${v}" ${c.brand===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label class="label" for="${prefix}category">Danh mục · nhóm ${i+1}</label><select class="input" id="${prefix}category" data-assistant-refresh="${i}">${assistantCategoryOptions(c)}</select></div></div><div class="two">${field('Giá chào từ (đ) · nhóm '+(i+1),prefix+'min',c.min,'number','min="0"')}${field('Giá chào tối đa (đ) · nhóm '+(i+1),prefix+'max',c.max??'','number','min="1" placeholder="Không giới hạn"')}</div><div class="two">${field('Số sản phẩm tối đa · nhóm '+(i+1),prefix+'limit',c.limit,'number','min="1" max="200"')}<div class="field"><label class="label" for="${prefix}pack">Đơn vị ngân sách · nhóm ${i+1}</label><select class="input" id="${prefix}pack"><option value="1" ${c.packSize===1?'selected':''}>Một sản phẩm</option><option value="10" ${c.packSize===10?'selected':''}>Bộ 10 sản phẩm</option></select></div></div>${c.provider?`<p class="inline-note">${esc(c.provider.name)}: giá niêm yết ×${100-c.provider.discount}% + ${money(c.provider.fee)}. Mẫu chưa công khai giá: ${c.provider.includeContact?"Liên hệ, chỉ lấy khi không đặt ngân sách":"bỏ qua"}.</p>`:""}${field('Từ khóa bổ sung · nhóm '+(i+1),prefix+'keywords',(c.keywords||[]).join(', '),'text','placeholder="Ngăn cách bằng dấu phẩy"')}</div></article>`;}
function assistantView(){return `<div class="page-head"><div><div class="eyebrow">TRỢ LÝ SẢN PHẨM</div><h1>Nhiều món quà, nhiều lựa chọn.</h1><p>Tạo nhiều nhóm danh mục và ngân sách trong cùng một báo giá.</p></div>${btn('Thêm danh mục','assistant-add','plus')}</div><div class="panel"><div class="panel-body"><label class="label" for="assistant-prompt">Anh/chị muốn tạo báo giá gì?</label><div class="field"><label class="label" for="a-stock-source">Nguồn kiểm tra tồn kho</label><select class="input" id="a-stock-source"><option value="website" ${assistantStockSource==='website'?'selected':''}>Còn hàng trên website nhà cung cấp</option><option value="crm" ${assistantStockSource==='crm'?'selected':''}>Tồn khả dụng thực tế trên CRM</option></select></div><textarea class="input" id="assistant-prompt" maxlength="1000" placeholder="Ly sứ dưới 350k + ly dưỡng sinh từ 350–800k + bộ trà dưới 2tr">${esc(assistantPrompt)}</textarea><p class="hint">Nối các yêu cầu bằng dấu + hoặc “và”. Mỗi danh mục có thể dùng mức giá riêng.</p>${btn('Phân tích yêu cầu','assistant-interpret','search','primary')} ${btn('Tải danh mục website','assistant-categories','grid')} ${assistantEngine?`<span class="tag">${assistantEngine==='cloudflare_ai'?'Diễn giải bằng AI':'Bộ lọc câu lệnh'}</span>`:''}${assistantWarning?`<p class="inline-note">${esc(assistantWarning)}</p>`:''}<p class="hint">${assistantCatalog.length?assistantCatalog.length+' danh mục từ website đã sẵn sàng.':'Có thể chọn danh mục thông dụng hoặc tải danh mục đầy đủ từ website.'}</p></div></div><div class="assistant-groups">${assistantGroups.map(assistantGroupCard).join('')}</div>${assistantGroups.length?`<div class="panel" style="margin-top:20px"><div class="panel-body">${btn('Thêm danh mục khác','assistant-add','plus')}<label class="switch-row">${assistantStockSource==='crm'?'Chỉ lấy mã có tồn khả dụng CRM > 0':'Chỉ lấy sản phẩm còn hàng trên website'}<input type="checkbox" checked disabled></label><div class="field"><label class="label" for="a-mode">Đưa vào báo giá</label><select id="a-mode" class="input"><option value="replace" ${assistantMode==='replace'?'selected':''}>Tạo danh sách mới (giữ thư viện cũ)</option><option value="append" ${assistantMode==='append'?'selected':''}>Thêm vào danh sách đang chọn</option></select></div><p class="hint">LocknLock: niêm yết ×60% +15.000đ. Minh Long: ×90% +15.000đ. Lọc theo giá chào đã gồm phụ phí. Tối đa 12 nhóm, 500 sản phẩm/lần; loại trùng link giữa các nhóm. Báo giá phân theo ngân sách → thương hiệu → danh mục, 4 SP/trang.</p>${btn('Tìm tất cả nhóm & tạo báo giá','assistant-search','plus','primary')}</div></div>`:''}${assistantResult?`<div class="inline-note"><strong>Đã thêm ${assistantResult.products.length} sản phẩm${assistantResult.products.every(p=>p.crmStock)?' · Đã xác minh tồn khả dụng CRM':''}</strong> · ${esc(new Date(assistantResult.checkedAt).toLocaleString('vi-VN'))}${(assistantResult.groupReports||[]).map(g=>`<p>Nhóm ${g.index}: ${g.count} sản phẩm mới.</p>`).join('')}${assistantResult.moreAvailable?'<p>Còn kết quả khác hoặc đã đạt giới hạn; hãy thu hẹp tiêu chí.</p>':''}${assistantResult.errors.map(e=>`<p>${esc(e)}</p>`).join('')}${btn('Xem báo giá','nav','file','small','data-view="quote"')}</div>`:''}`;}
function readAssistantGroups(){assistantPrompt=$('#assistant-prompt')?.value??assistantPrompt;assistantMode=$('#a-mode')?.value||assistantMode;assistantStockSource=$('#a-stock-source')?.value||assistantStockSource;assistantGroups=assistantGroups.map((c,i)=>{const p='#ag-'+i+'-',selected=$(p+'category')?.value;if(selected===undefined)return c;if(c.provider){const selectedCollection=$(p+'category'),provider={...c.provider,collectionUrl:selectedCollection.value,categoryLabel:selectedCollection.selectedOptions[0].textContent};return {...c,provider,categoryLabel:provider.categoryLabel,stockSource:assistantStockSource,min:$(p+'min').value,max:$(p+'max').value,limit:Number($(p+'limit').value),packSize:Number($(p+'pack').value),keywords:$(p+'keywords').value.split(',').map(s=>s.trim()).filter(Boolean)}};const parts=selected.split(':'),web=parts[0]==='web',id=web?Number(parts[2]):0;return {...c,stockSource:assistantStockSource,brand:web?parts[1]:$(p+'brand').value,type:web?'website':parts[1],categoryId:id,categoryLabel:web?(assistantCatalog.find(x=>x.id===id&&x.brand===parts[1])?.label||''):'',min:$(p+'min').value,max:$(p+'max').value,limit:Number($(p+'limit').value),packSize:Number($(p+'pack').value),keywords:$(p+'keywords').value.split(',').map(s=>s.trim()).filter(Boolean)}});return assistantGroups;}
async function assistantCall(body,endpoint='api/assistant'){const headers={'Content-Type':'application/json'};try{const token=localStorage.getItem('bn-v2-session')||sessionStorage.getItem('bn-v2-session')||'';if(token)headers.Authorization='Bearer '+token}catch{}const r=await fetch(new URL(endpoint,import.meta.url),{method:'POST',headers,body:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw Error(data.error||'Chưa thực hiện được yêu cầu.');return data;}

async function assistantInterpret(){assistantPrompt=$('#assistant-prompt').value;const externalLink=assistantPrompt.match(/https:\/\/[^\s<>]+/i)?.[0];if(externalLink&&!/^https:\/\/(?:www\.)?(?:locknlockonline|minhlongonline)\.com(?:\/|$)/i.test(externalLink))return proposeBrand(externalLink);return interpretKnown();}
async function interpretKnown(){assistantPrompt=$('#assistant-prompt').value;assistantStockSource=$('#a-stock-source').value;setBusy('Đang phân tích các nhóm yêu cầu…','Đọc danh mục trên website và phân chia ngân sách.');try{const r=await assistantCall({action:'interpret',prompt:assistantPrompt,stockSource:assistantStockSource});if(r.diagnostic)console.warn('Catalogue AI status:',r.diagnostic);assistantGroups=r.groups||[r.criteria];assistantStockSource=r.stockSource||assistantGroups[0]?.stockSource||assistantStockSource;assistantCatalog=r.catalog||assistantCatalog;assistantWarning=r.warning;assistantEngine=r.engine;assistantResult=null;render()}finally{clearBusy()}}
async function loadAssistantCategories(){readAssistantGroups();setBusy('Đang tải danh mục website…');try{const r=await assistantCall({action:'categories'});assistantCatalog=r.catalog;render();toast('Đã tải '+r.catalog.length+' danh mục từ hai website.')}finally{clearBusy()}}
async function assistantAdd(index=null,range=false){readAssistantGroups();if(assistantGroups.length>=12)throw Error('Mỗi lần tạo tối đa 12 nhóm.');if(!assistantCatalog.length){await loadAssistantCategories()}const previous=index===null?null:assistantGroups[index];const c=previous?structuredClone(previous):{brand:'Minh Long',type:'ly-su',min:0,max:null,limit:100,packSize:1,keywords:[]};if(range){c.min=c.max?Number(c.max)+1:0;c.max=[350000,800000,1400000,2500000].find(n=>n>=c.min)??null}assistantGroups.push(c);render();}
async function assistantSearch(){const groups=readAssistantGroups(),append=assistantMode==='append';setBusy('Đang tìm sản phẩm của các nhóm…','Kiểm tra còn hàng, tính giá chào và loại sản phẩm trùng.');try{const r=await assistantCall({action:'search',groups,pricing:{lockDiscount:40,minhDiscount:10,fee:15000}});if(!r.products.length)throw Error(r.errors?.join(' ')||'Chưa có sản phẩm phù hợp. Hãy chỉnh danh mục hoặc ngân sách.');const incoming=r.products.map(raw=>{const prior=state.products.find(p=>p.url===raw.url);return validateProduct({...prior,...raw,id:prior?.id,collection:raw.collection||prior?.collection,pattern:raw.pattern||prior?.pattern,color:raw.color||prior?.color,createdAt:raw.createdAt||prior?.createdAt,createdAtSource:raw.createdAt?raw.createdAtSource:prior?.createdAtSource});});if(state.products.length+incoming.filter(p=>!state.products.some(q=>q.id===p.id)).length>1000)throw Error('Thư viện vượt 1.000 sản phẩm. Hãy giảm giới hạn tìm kiếm.');const merged=new Map(state.products.map(p=>[p.id,p]));for(const p of incoming)merged.set(p.id,p);state.products=[...merged.values()];state.selected=[...new Set([...(append?state.selected:[]),...incoming.map(p=>p.id)])];const scope=new Set(state.settings.bundle10Ids||[]);for(const p of incoming){if(r.products.find(q=>q.url===p.url)?.packSize===10)scope.add(p.id);else scope.delete(p.id)}state.settings.bundle10Ids=[...scope];if(r.products.some(p=>p.packSize===10))state.settings.bundle10=true;setSelectionSort(state,'price');assistantResult=r;page=0;scheduleSave();render();toast('Đã thêm '+incoming.length+' sản phẩm từ '+groups.length+' nhóm.')}finally{clearBusy()}}

function importUrlKey(raw){try{const u=new URL(raw);return u.hostname.replace(/^www\./,'').toLowerCase()+u.pathname.replace(/\/$/,'')}catch{return ''}}
async function editPageText(){const slide=makeSlides(state)[page],key=slideKey(slide),fields=[];await drawSlide(document.createElement('canvas'),slide,state,page+1,makeSlides(state).length,null,1,fields);let dialog=$('#page-text-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='page-text-dialog';dialog.className='modal';document.body.append(dialog)}dialog.innerHTML=`<form id="page-text-form"><div class="modal-head"><div><h2>Sửa chữ · Trang ${page+1}</h2><p>Chỉ áp dụng cho trang này trong bản xem trước, PDF và PowerPoint.</p></div></div><div class="modal-body"><p class="hint">Sửa nội dung hiển thị. Muốn thay đổi giá tính toán, sửa thông tin sản phẩm trong báo giá.</p>${fields.map((f,i)=>`<div class="field"><label class="label" for="page-text-${i}">Nội dung ${i+1}</label><textarea class="input" id="page-text-${i}" data-position="${f.position}" maxlength="2000">${esc(f.value)}</textarea></div>`).join('')}</div><div class="modal-foot"><button type="button" class="btn" id="page-text-reset">Khôi phục chữ theo mẫu</button><button type="button" class="btn" id="page-text-cancel">Hủy</button><button type="submit" class="btn primary">Lưu chữ trang này</button></div></form>`;$('#page-text-cancel').onclick=()=>dialog.close();$('#page-text-reset').onclick=()=>{if(state.pageText)delete state.pageText[key];dialog.close();changed()};$('#page-text-form').onsubmit=e=>{e.preventDefault();const changes={};for(const [i,f]of fields.entries()){const value=$('#page-text-'+i).value;if(value!==f.original)changes[f.position]=value}state.pageText||={};state.pageText[key]=changes;dialog.close();changed()};dialog.showModal();}

async function fetchImportBatches(rows){const groups=new Map(),results=new Map();for(const p of rows){if(!p.url||p.name&&Number(p.regular)&&p.image)continue;try{const u=new URL(p.url),host=u.hostname.replace(/^www\./,'');if(!['locknlockonline.com','minhlongonline.com'].includes(host))throw Error('Chỉ hỗ trợ link LocknLock và Minh Long.');if(!groups.has(host))groups.set(host,[]);groups.get(host).push(p.url)}catch(e){results.set(importUrlKey(p.url),{error:e.message})}}const batches=[];for(const urls of groups.values())for(let i=0;i<urls.length;i+=20)batches.push(urls.slice(i,i+20));let done=0,total=batches.reduce((n,b)=>n+b.length,0);$('#busy-detail').textContent=`Đang lấy dữ liệu theo lô · 0 / ${total} mã`;await mapConcurrent(batches,3,async urls=>{try{const r=await fetch(new URL('api/products',import.meta.url),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({urls})});const data=await r.json();if(!r.ok)throw Error(data.error||'Chưa lấy được dữ liệu website.');for(const p of data.products)results.set(importUrlKey(p.url),{product:p.product});for(const e of data.errors)results.set(importUrlKey(e.url),{error:e.error})}catch(e){for(const url of urls)results.set(importUrlKey(url),{error:e.message})}finally{done+=urls.length;$('#busy-detail').textContent=`Đã lấy dữ liệu ${done} / ${total} mã · tối đa 20 mã/lô`;}});return results;}

function textRegionButton(field){const b=document.createElement('button');b.type='button';b.className='text-region';b.dataset.action='inline-text';b.dataset.position=field.position;b.setAttribute('aria-label','Sửa chữ: '+field.value.slice(0,160));b.title='Bấm để sửa chữ';Object.assign(b.style,{left:field.x/12.8+'%',top:field.y/7.2+'%',width:field.w/12.8+'%',height:field.h/7.2+'%'});return b;}
function mountTextLayer(slide){const layer=$('#text-edit-layer');if(!layer)return;layer.replaceChildren();if(slide.type==='empty')return;for(const field of previewTextBoxes)layer.append(textRegionButton(field));}
function inlineTextEditor(position,button){const field=previewTextBoxes.find(f=>f.position===position);if(!field)return;const key=previewTextKey,input=document.createElement('textarea');input.className='inline-text-input';input.value=field.value;input.maxLength=2000;input.setAttribute('aria-label','Chỉnh chữ trực tiếp');input.title='Bấm ra ngoài hoặc Ctrl+Enter để lưu; Esc để hủy';Object.assign(input.style,{left:field.x/12.8+'%',top:field.y/7.2+'%',width:field.w/12.8+'%',height:Math.max(field.h,28)/7.2+'%',fontSize:Math.max(8,field.size*$('#slide-canvas').clientWidth/1280)+'px',fontWeight:field.bold?'700':'400',color:field.color,textAlign:field.align});let finished=false;
 const finish=save=>{if(finished)return;finished=true;const value=input.value;if(save){state.pageText||={};state.pageText[key]||={};if(value===field.original)delete state.pageText[key][position];else state.pageText[key][position]=value;scheduleSave();}const replacement=textRegionButton({...field,value:save?value:field.value});input.replaceWith(replacement);if(save)updatePreview(false);};
 input.addEventListener('blur',()=>finish(true));input.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();finish(false)}else if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();finish(true)}});button.replaceWith(input);input.focus();input.setSelectionRange(0,input.value.length);
}

let pendingBrand=null;
async function proposeBrand(url){setBusy('Đang nhận diện thương hiệu từ link…');try{pendingBrand=await assistantCall({action:'brand-preview',url,prompt:assistantPrompt});const d=$('#product-dialog'),b=pendingBrand;d.innerHTML=`<form id="brand-confirm-form"><div class="modal-head"><div><h2>Xác nhận thương hiệu từ link</h2><p>Kiểm tra tên, nguồn dữ liệu và cách tính giá trước khi thêm.</p></div><button type="button" class="icon-btn" data-action="close-modal" aria-label="Đóng">${icon('close')}</button></div><div class="modal-body">${field('Tên thương hiệu','b-name',b.name,'text','required maxlength="50"')}${field('Website nguồn','b-origin',b.origin,'text','readonly')}${field('Link danh mục / sản phẩm','b-link',b.collectionUrl,'text','readonly')}${field('Tên danh mục','b-category',b.categoryLabel,'text','required maxlength="70"')}<div class="two">${field('Chiết khấu từ giá niêm yết (%)','b-discount',b.discount,'number','min="0" max="99.9" step="0.1" required')}${field('Phụ phí VAT + in (đ)','b-fee',b.fee,'number','min="0" max="100000000" required')}</div><p class="inline-note">Thương hiệu mới mặc định giảm 0%, phụ phí 15.000đ. Anh/chị xác nhận hoặc sửa trước khi dùng.</p><label class="switch-row">Xác nhận giá website là VND<input id="b-vnd" type="checkbox" ${b.currency==='VND'?'checked':''} required></label><label class="switch-row">Cho phép sản phẩm chưa công khai giá, hiển thị “Liên hệ”<input id="b-contact" type="checkbox" checked></label><p class="hint">Sản phẩm “Liên hệ” nằm trong nhóm riêng, không lọc vào ngân sách bằng giá 0đ.</p>${b.warning?`<p class="inline-note">${esc(b.warning)}</p>`:''}<p class="hint">${b.sampleCount||0} sản phẩm mẫu đọc được; ${b.unpricedCount||0} mẫu chưa công khai giá.</p><p id="brand-error" class="error" role="alert"></p></div><div class="modal-foot"><button type="button" class="btn" data-action="close-modal">Hủy</button><button class="btn primary" type="submit">Xác nhận & thêm nhóm danh mục</button></div></form>`;d.showModal()}finally{clearBusy()}}
document.addEventListener('submit',e=>{if(e.target.id!=='brand-confirm-form')return;e.preventDefault();try{const name=$('#b-name').value.trim(),discount=Number($('#b-discount').value),fee=Number($('#b-fee').value);if(!name||['LocknLock','Minh Long','both'].includes(name)||!Number.isFinite(discount)||discount<0||discount>=100||!Number.isFinite(fee)||fee<0)throw Error('Kiểm tra tên thương hiệu và công thức giá.');if(assistantGroups.length>=12)throw Error('Tối đa 12 nhóm.');const b={...pendingBrand,name,categoryLabel:$('#b-category').value.trim(),discount,fee,currency:'VND',includeContact:$('#b-contact').checked};state.customBrands=[...(state.customBrands||[]).filter(x=>x.origin!==b.origin||x.name!==b.name),b].slice(-30);assistantGroups.push({brand:b.name,type:'website',categoryId:0,categoryLabel:b.categoryLabel,provider:b,min:0,max:null,limit:100,packSize:1,keywords:[],stockSource:assistantStockSource});assistantResult=null;$('#product-dialog').close();scheduleSave();render();toast('Đã thêm thương hiệu '+b.name+'. Kiểm tra ngân sách rồi bấm tìm sản phẩm.')}catch(error){$('#brand-error').textContent=error.message}});

function selectionTools(){
 const mode=state.settings.selectionSort==='price'&&!state.settings.sortPrice?'manual':state.settings.selectionSort||'manual',fields={newest:'createdAt',collection:'collection',category:'category',pattern:'pattern',color:'color'},missing=fields[mode]?selectedProducts(state).filter(p=>!p[fields[mode]]).length:0;
 return `<div class="selection-tools"><label for="selection-sort">Sắp xếp theo<select id="selection-sort" class="input">${SELECTION_SORTS.map(([value,label])=>`<option value="${value}" ${mode===value?'selected':''}>${label}</option>`).join('')}</select></label>${btn('Đọc thuộc tính nguồn','refresh-details','','small')}</div><p class="selection-hint" id="selection-reorder-help">Kéo tay nắm hoặc dùng phím ↑ ↓ để đổi vị trí. Bản xuất vẫn nhóm theo ngân sách → thương hiệu → danh mục.${missing?`<br>${missing} sản phẩm chưa có ${mode==='newest'?'ngày tạo trên web/CRM':'thuộc tính này'}; được xếp sau. Đọc từ nguồn hoặc bổ sung trong Sửa sản phẩm.`:''}</p>`;
}
async function refreshSelectionDetails(){
 if(busy)return;const chosen=selectedProducts(state);setBusy('Đang đọc thuộc tính sản phẩm…','Chỉ bổ sung thông tin còn thiếu; không đổi giá, số lượng hoặc tồn.');let changedCount=0,crmError='',webErrors=0;
 try{
  const web=await fetchImportBatches(chosen.map(p=>({url:p.url})));let crm=new Map();
  const skus=chosen.map(p=>p.sku).filter(Boolean);
  if(skus.length)try{const result=await assistantCall({skus},'api/product-metadata');crm=new Map(result.products.map(p=>[String(p.sku).trim().toUpperCase(),p]));}catch(e){crmError=e.message;}
  for(const original of chosen){const p=state.products.find(p=>p.id===original.id);if(!p)continue;const result=web.get(importUrlKey(p.url));if(result?.error)webErrors++;const a=result?.product||{},b=crm.get(String(p.sku).trim().toUpperCase())||{},extra={};for(const field of ['collection','pattern','color'])if(!p[field]&&(a[field]||b[field]))extra[field]=a[field]||b[field];if(!p.createdAt&&(a.createdAt||b.createdAt)){extra.createdAt=a.createdAt||b.createdAt;extra.createdAtSource=a.createdAt?'web':'crm';}if(Object.keys(extra).length){Object.assign(p,validateProduct({...p,...extra}));changedCount++;}}
  changed();toast('Đã bổ sung thuộc tính cho '+changedCount+' sản phẩm.'+(webErrors?' '+webErrors+' link chưa đọc được.':'')+(crmError?' CRM: '+crmError:''));
 }finally{clearBusy();}
}
function openExportDialog(type){
 if(busy||!state.selected.length)return;
 const snapshot=structuredClone(state),slides=makeSlides(snapshot),total=slides.length,current=Math.min(page+1,total),dialog=$('#export-dialog');
 dialog.innerHTML=`<form id="export-form"><div class="modal-head"><div><h2>Xuất ${type==='pdf'?'PDF':'PowerPoint'}</h2><p>Báo giá có ${total} trang, theo số trong bản xem trước.</p></div><button type="button" class="icon-btn" data-export-close aria-label="Đóng">${icon('close')}</button></div><div class="modal-body export-options"><label><input type="radio" name="scope" value="all" checked> Tất cả ${total} trang</label><label><input type="radio" name="scope" value="current"> Trang đang xem (${current})</label><label><input type="radio" name="scope" value="custom"> Các trang tự chọn</label><label class="label" for="export-pages">Số trang hoặc khoảng trang</label><input class="input" id="export-pages" placeholder="Ví dụ: 1, 3-5" maxlength="1000" disabled><p class="hint">Gồm cả bìa, trang chia ngân sách và cảm ơn nếu có. Trang trùng được bỏ; xuất theo thứ tự và giữ số trang của bản xem trước.</p><p id="export-error" class="error" role="alert"></p></div><div class="modal-foot"><button type="button" class="btn" data-export-close>Huỷ</button><button type="submit" class="btn primary">Xuất ${type==='pdf'?'PDF':'PowerPoint'}</button></div></form>`;
 const form=dialog.querySelector('form'),input=dialog.querySelector('#export-pages');for(const button of dialog.querySelectorAll('[data-export-close]'))button.addEventListener('click',()=>dialog.close());
 form.addEventListener('change',()=>{input.disabled=form.elements.scope.value!=='custom';if(!input.disabled)input.focus();dialog.querySelector('#export-error').textContent='';});
 form.addEventListener('submit',event=>{event.preventDefault();try{const scope=form.elements.scope.value,numbers=scope==='all'?Array.from({length:total},(_,i)=>i+1):scope==='current'?[current]:parsePageSelection(input.value,total);dialog.close();exportFile(type,snapshot,numbers);}catch(e){dialog.querySelector('#export-error').textContent=e.message;input.focus();}});
 dialog.showModal();
}
